/* ---- A row brought into view by a map selection (maps-2) ----
   Clicking a pin on the map opens the detail panel and now also scrolls the
   result list to that record (results.js `revealRow`). The brief marking says
   whose row that is; it is not the selected style (`.zh-result[aria-current]`
   stays after the mark is gone). */
.zh-result.is-revealed {
  outline: 3px solid var(--zh-color-accent-dark);
  outline-offset: 2px;
  border-left-color: var(--zh-color-accent-dark);
}

@media (prefers-reduced-motion: no-preference) {
  .zh-result.is-revealed {
    animation: zh-row-reveal 700ms var(--zh-easing-decelerate) 1;
  }
}

@keyframes zh-row-reveal {
  from {
    background: var(--zh-darkblue-soft);
  }
  to {
    background: var(--zh-color-surface);
  }
}

/* ---- Windows high contrast / forced colors (maps-2) ----
   Forced-colors mode replaces every author colour, so the states the app
   communicates with `background-color` would disappear: a selected pin, the
   hovered row, the brushed decade, a footprint and the histogram bars would all
   look alike. These rules use system colour keywords, the only colours the mode
   keeps, and prefer borders/outlines over fills so every state stays readable.

   Values are the documented CSS system colours
   (https://www.w3.org/TR/css-color-4/#css-system-colors), not author colours. */
@media (forced-colors: active) {
  .map-marker {
    border: 2px solid ButtonBorder;
    background: ButtonFace;
    color: ButtonText;
    forced-color-adjust: none;
  }

  .map-marker.is-selected,
  .map-marker[aria-current='true'] {
    background: Highlight;
    color: HighlightText;
    outline: 3px solid Highlight;
    outline-offset: 1px;
  }

  .map-marker.is-preview {
    outline: 3px dashed Highlight;
    outline-offset: 2px;
  }

  .map-marker.map-cluster {
    border-width: 3px;
  }

  .zh-result {
    border: 1px solid ButtonBorder;
    border-left: 4px solid ButtonBorder;
  }

  .zh-result[aria-current='true'],
  .zh-result.is-revealed {
    border: 3px double Highlight;
    border-left: 8px solid Highlight;
    outline: 1px solid Highlight;
    outline-offset: 1px;
  }

  .zh-result.is-preview {
    border: 3px dashed Highlight;
  }

  /* Outline-only footprints: their border colour is forced, the fill is not the
     information — the hovered/selected one gets a second outline instead. */
  .map-footprint {
    border: 2px solid CanvasText;
  }

  .map-footprint.is-preview,
  .map-footprint.is-selected {
    border: 3px dashed CanvasText;
    background: none;
  }

  .zh-histogram__bar {
    background: ButtonText;
    opacity: 1;
  }

  .zh-histogram__bin[aria-current='true'] .zh-histogram__bar,
  .zh-histogram__bin.is-brushing .zh-histogram__bar {
    background: Highlight;
  }

  .zh-histogram__bin.is-empty .zh-histogram__bar {
    background: GrayText;
    opacity: 1;
  }

  .zh-histogram__bin.is-brushing {
    outline: 1px solid Highlight;
  }
}
