#!/usr/bin/env node
/** Scratch probe (not part of the repo): does a pin click bring its row into
 *  view on desktop, and what do the forced-colors rules compute to? */
import { spawn } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const BASE = process.env.BASE ?? 'http://127.0.0.1:8787';
const PORT = 9334;
const binary = ['/usr/bin/chromium', '/usr/bin/chromium-browser', '/usr/bin/google-chrome'].find(Boolean);
const userDataDir = await mkdtemp(path.join(tmpdir(), 'probe-'));
const child = spawn(binary, ['--headless=new', `--remote-debugging-port=${PORT}`, `--user-data-dir=${userDataDir}`, '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--window-size=1440,950', 'about:blank'], { stdio: ['ignore', 'ignore', 'ignore'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function endpoint(p) {
  for (let i = 0; i < 40; i += 1) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}${p}`);
      if (res.ok) return res.json();
    } catch { /* not up */ }
    await sleep(250);
  }
  throw new Error('no devtools endpoint');
}
const conn = await endpoint('/json/version');
const ws = new WebSocket(conn.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(msg.error.message)) : resolve(msg.result);
  }
};
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const n = ++id;
  pending.set(n, { resolve, reject });
  ws.send(JSON.stringify({ id: n, method, params }));
  setTimeout(() => { if (pending.delete(n)) reject(new Error(`${method} timeout`)); }, 30000);
});
const evalJs = async (expression) => {
  const { result, exceptionDetails } = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (exceptionDetails) throw new Error(exceptionDetails.exception?.description ?? exceptionDetails.text);
  return result?.value;
};
const waitFor = async (expression, label, timeout = 20000) => {
  const end = Date.now() + timeout;
  while (Date.now() < end) {
    try { const v = await evalJs(expression); if (v) return v; } catch { /* retry */ }
    await sleep(250);
  }
  throw new Error(`timeout: ${label}`);
};

await send('Page.enable');
await send('Runtime.enable');

// --- 1. desktop: pin click brings the row into view -------------------------
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 950, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: `${BASE}/` });
await waitFor(`document.querySelectorAll('#result-list > *').length > 20`, 'rows');
await waitFor(`document.querySelectorAll('.map-marker:not(.map-cluster)').length > 0`, 'markers');
await sleep(800);

const target = await evalJs(`(() => {
  const rows = [...document.querySelectorAll('#result-list > *')];
  const index = new Map(rows.map((li, i) => [li.querySelector('button.zh-result')?.dataset.recordId, i]));
  const markers = [...document.querySelectorAll('.map-marker:not(.map-cluster)')];
  let best = null;
  for (const marker of markers) {
    const i = index.get(marker.dataset.id);
    if (i === undefined) continue;
    if (!best || i < best.index) best = { index: i, id: marker.dataset.id };
  }
  if (!best) return null;
  const row = rows[best.index].getBoundingClientRect();
  window.scrollTo({ top: window.scrollY + row.top + 240, behavior: 'instant' });
  const marker = document.querySelector('.map-marker[data-id="' + CSS.escape(best.id) + '"]');
  const r = marker.getBoundingClientRect();
  return { ...best, rowTop: row.top, scrollY: window.scrollY, markerRect: { x: r.left + r.width / 2, y: r.top + r.height / 2 }, mapVisible: document.querySelector('.app-mapwrap').getBoundingClientRect().top < window.innerHeight };
})()`);
console.log('target:', JSON.stringify(target));
const afterScroll = await evalJs(`(() => { const li = [...document.querySelectorAll('#result-list > *')].find((n) => n.querySelector('button')?.dataset.recordId === ${JSON.stringify(target.id)}); const r = li.getBoundingClientRect(); return { scrollY: window.scrollY, top: r.top, bottom: r.bottom, inView: r.top >= 0 && r.bottom <= window.innerHeight, mapVisible: document.querySelector('.app-mapwrap').getBoundingClientRect().top < window.innerHeight }; })()`);
console.log('after deliberate scroll:', JSON.stringify(afterScroll));

const x = Math.round(target.markerRect.x);
const y = Math.round(target.markerRect.y);
await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y, button: 'left' });
await send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 });
await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 });
await sleep(600);
const afterClick = await evalJs(`(() => {
  const li = [...document.querySelectorAll('#result-list > *')].find((n) => n.querySelector('button')?.dataset.recordId === ${JSON.stringify(target.id)});
  const r = li.getBoundingClientRect();
  const detail = document.querySelector('#detail');
  return {
    search: location.search,
    scrollY: window.scrollY,
    top: Math.round(r.top), bottom: Math.round(r.bottom),
    inView: r.top >= 0 && r.bottom <= window.innerHeight,
    revealed: li.querySelector('button').classList.contains('is-revealed'),
    ariaCurrent: li.querySelector('button').getAttribute('aria-current'),
    drawerLeft: detail.hidden ? null : Math.round(detail.getBoundingClientRect().left),
    rowRight: Math.round(r.right),
    mapVisible: document.querySelector('.app-mapwrap').getBoundingClientRect().top < window.innerHeight,
  };
})()`);
console.log('after pin click:', JSON.stringify(afterClick));

// --- 2. mobile: the page must not move -------------------------------------
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
await send('Page.navigate', { url: `${BASE}/` });
await waitFor(`document.querySelectorAll('#result-list > *').length > 20`, 'mobile rows');
await waitFor(`document.querySelectorAll('.map-marker:not(.map-cluster)').length > 0`, 'mobile markers');
await sleep(800);
const mobileTarget = await evalJs(`(() => {
  const marker = document.querySelector('.map-marker:not(.map-cluster)');
  const r = marker.getBoundingClientRect();
  return { id: marker.dataset.id, x: r.left + r.width / 2, y: r.top + r.height / 2, scrollY: window.scrollY };
})()`);
await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: Math.round(mobileTarget.x), y: Math.round(mobileTarget.y) });
await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: Math.round(mobileTarget.x), y: Math.round(mobileTarget.y), button: 'left', clickCount: 1 });
await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: Math.round(mobileTarget.x), y: Math.round(mobileTarget.y), button: 'left', clickCount: 1 });
await sleep(600);
const mobileAfter = await evalJs(`({ scrollY: window.scrollY, sel: new URLSearchParams(location.search).get('sel'), revealed: document.querySelectorAll('.zh-result.is-revealed').length })`);
console.log('mobile before/after:', JSON.stringify({ ...mobileTarget, after: mobileAfter }));

// --- 3. forced colors ------------------------------------------------------
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 950, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: `${BASE}/?sel=${encodeURIComponent(afterClick.search.match(/sel=([^&]*)/)?.[1] ?? '')}` });
await waitFor(`document.querySelectorAll('#result-list > *').length > 20`, 'rows for forced colors');
await sleep(900);
await send('Emulation.setEmulatedMedia', { features: [{ name: 'forced-colors', value: 'active' }] });
await sleep(300);
const forced = await evalJs(`(() => {
  const style = (node) => { const s = getComputedStyle(node); return { border: s.borderTopWidth + ' ' + s.borderTopStyle + ' ' + s.borderTopColor, borderLeft: s.borderLeftWidth + ' ' + s.borderLeftColor, outline: s.outlineWidth + ' ' + s.outlineStyle + ' ' + s.outlineColor, background: s.backgroundColor, color: s.color }; };
  const selected = document.querySelector('.zh-result[aria-current="true"]');
  const other = document.querySelector('.zh-result:not([aria-current="true"])');
  const marker = document.querySelector('.map-marker[data-id="' + CSS.escape(${JSON.stringify(target.id)}) + '"]');
  const bar = document.querySelector('.zh-histogram__bar');
  const currentBar = document.querySelector('.zh-histogram__bin[aria-current="true"] .zh-histogram__bar');
  const footprint = document.querySelector('.map-footprint');
  return {
    matches: matchMedia('(forced-colors: active)').matches,
    selected: selected ? style(selected) : null,
    other: other ? style(other) : null,
    marker: marker ? style(marker) : null,
    bar: bar ? style(bar) : null,
    currentBar: currentBar ? style(currentBar) : null,
    footprint: footprint ? style(footprint) : null,
  };
})()`);
console.log('forced colors:', JSON.stringify(forced, null, 1));
await send('Emulation.setEmulatedMedia', { features: [] });
ws.close();
child.kill('SIGKILL');
process.exit(0);

