#!/usr/bin/env node
/** Scratch probe: what does Chrome's forced-colors emulation do to system
 *  colour keywords and to our appended @media (forced-colors: active) rules? */
import { spawn } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const BASE = process.env.BASE ?? 'http://127.0.0.1:8787';
const PORT = 9335;
const binary = ['/usr/bin/chromium', '/usr/bin/chromium-browser', '/usr/bin/google-chrome'].find(Boolean);
const userDataDir = await mkdtemp(path.join(tmpdir(), 'probe2-'));
const child = spawn(binary, ['--headless=new', `--remote-debugging-port=${PORT}`, `--user-data-dir=${userDataDir}`, '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--window-size=1440,950', 'about:blank'], { stdio: ['ignore', 'ignore', 'ignore'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) {
  for (let i = 0; i < 40; i += 1) {
    try { const res = await fetch(`http://127.0.0.1:${PORT}${p}`); if (res.ok) return res.json(); } catch { /* not up */ }
    await sleep(250);
  }
  throw new Error('no devtools endpoint');
}
const pages = await endpoint('/json/list');
const page = pages.find((t) => t.type === 'page' && t.webSocketDebuggerUrl);
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(msg.error.message)) : resolve(msg.result);
  }
};
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const n = ++id;
  pending.set(n, { resolve, reject });
  ws.send(JSON.stringify({ id: n, method, params }));
  setTimeout(() => { if (pending.delete(n)) reject(new Error(`${method} timeout`)); }, 30000);
});
const evalJs = async (expression) => {
  const { result, exceptionDetails } = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (exceptionDetails) throw new Error(exceptionDetails.exception?.description ?? exceptionDetails.text);
  return result?.value;
};
const waitFor = async (expression, label, timeout = 20000) => {
  const end = Date.now() + timeout;
  while (Date.now() < end) {
    try { const v = await evalJs(expression); if (v) return v; } catch { /* retry */ }
    await sleep(250);
  }
  throw new Error(`timeout: ${label}`);
};

await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 950, deviceScaleFactor: 1, mobile: false });

// A record with a pin, selected through a real pin click.
await send('Page.navigate', { url: `${BASE}/` });
await waitFor(`document.querySelectorAll('#result-list > *').length > 20`, 'rows');
await waitFor(`document.querySelectorAll('.map-marker:not(.map-cluster)').length > 0`, 'markers');
await sleep(900);
await evalJs(`(() => { const m = document.querySelector('.map-marker:not(.map-cluster)'); const r = m.getBoundingClientRect(); window.__pin = { id: m.dataset.id, x: r.left + r.width / 2, y: r.top + r.height / 2 }; m.click(); return m.dataset.id; })()`);
await sleep(700);
const selected = await evalJs(`new URLSearchParams(location.search).get('sel')`);

const probe = `
(() => {
  const style = (node) => { const s = getComputedStyle(node); return {
    bg: s.backgroundColor, color: s.color,
    border: s.borderTopWidth + ' ' + s.borderTopStyle + ' ' + s.borderTopColor,
    borderLeftWidth: s.borderLeftWidth,
    outline: s.outlineWidth + ' ' + s.outlineStyle + ' ' + s.outlineColor,
    forcedAdjust: s.forcedColorAdjust };
  };
  const test = document.createElement('div');
  test.id = 'probe-test';
  test.setAttribute('style', 'background: ButtonText; color: CanvasText; border: 2px solid ButtonBorder; outline: 2px solid Highlight');
  document.body.append(test);
  const plain = document.createElement('div');
  plain.id = 'probe-plain';
  plain.setAttribute('style', 'background: #0070b4; color: #ffffff');
  document.body.append(plain);
  const row = document.querySelector('.zh-result[aria-current="true"]');
  const marker = document.querySelector('.map-marker.is-selected') || document.querySelector('.map-marker[data-id="' + CSS.escape(window.__pin.id) + '"]');
  const bar = document.querySelector('.zh-histogram__bar');
  const curBar = document.querySelector('.zh-histogram__bin[aria-current="true"] .zh-histogram__bar');
  const bin = document.querySelector('.zh-histogram__bin');
  const forcedRule = (() => {
    for (const sheet of document.styleSheets) {
      let rules = [];
      try { rules = [...sheet.cssRules]; } catch { continue; }
      for (const rule of rules) {
        if (rule.conditionText && /forced-colors/.test(rule.conditionText) && rule.matches) return { found: true, first: [...rule.cssRules].slice(0,3).map((r) => r.cssText.slice(0, 90)) };
      }
    }
    return { found: false };
  })();
  return { matches: matchMedia('(forced-colors: active)').matches, test: style(test), plain: style(plain), row: row ? style(row) : null, marker: marker ? style(marker) : null, bar: style(bar), curBar: curBar ? style(curBar) : null, bin: style(bin), forcedRule };
})()`;

const before = await evalJs(probe);
console.log('=== author colours (no emulation) ===');
console.log(JSON.stringify(before, null, 1));
await send('Emulation.setEmulatedMedia', { features: [{ name: 'forced-colors', value: 'active' }] });
await sleep(400);
const after = await evalJs(probe);
console.log('=== forced-colors: active ===');
console.log(JSON.stringify(after, null, 1));
console.log('selected record:', selected);
ws.close();
child.kill('SIGKILL');
process.exit(0);

